import Foundation

/// Reads USDZ packages: uncompressed zip archives whose entries are 64-byte aligned, the
/// first entry being the root layer (USDZ spec). Only stored (uncompressed) entries are
/// allowed, so no decompression library is needed.
public enum USDZArchive {
    public struct Entry: Equatable, Sendable {
        /// Path inside the package ("model.usdc", "0/texture.png").
        public var path: String
        public var offset: Int
        public var size: Int
    }

    public enum Failure: LocalizedError, Equatable {
        case notAPackage
        case compressed(String)
        case unsafePath(String)

        public var errorDescription: String? {
            switch self {
            case .notAPackage: "The file isn't a USDZ package."
            case .compressed(let name): "“\(name)” is compressed inside the USDZ, which the USDZ format doesn't allow."
            case .unsafePath(let name): "The USDZ contains an unsafe path (“\(name)”)."
            }
        }
    }

    /// The entries, in archive order (the first is the root layer).
    public static func entries(_ data: Data) throws -> [Entry] {
        let bytes = [UInt8](data)
        func u16(_ i: Int) -> Int { i + 1 < bytes.count ? Int(bytes[i]) | Int(bytes[i + 1]) << 8 : 0 }
        func u32(_ i: Int) -> Int { i + 3 < bytes.count ? u16(i) | u16(i + 2) << 16 : 0 }

        // End of central directory: signature 0x06054b50, searched backwards (a comment may follow).
        guard bytes.count >= 22 else { throw Failure.notAPackage }
        var eocd = -1
        var i = bytes.count - 22
        while i >= max(0, bytes.count - 22 - 65_535) {
            if u32(i) == 0x0605_4b50 { eocd = i; break }
            i -= 1
        }
        guard eocd >= 0 else { throw Failure.notAPackage }
        let count = u16(eocd + 10)
        var cursor = u32(eocd + 16)
        var result: [Entry] = []
        for _ in 0..<count {
            guard u32(cursor) == 0x0201_4b50 else { throw Failure.notAPackage }
            let method = u16(cursor + 10)
            let size = u32(cursor + 24)
            let nameLength = u16(cursor + 28), extraLength = u16(cursor + 30), commentLength = u16(cursor + 32)
            let localHeader = u32(cursor + 42)
            guard cursor + 46 + nameLength <= bytes.count else { throw Failure.notAPackage }
            let name = String(decoding: bytes[(cursor + 46)..<(cursor + 46 + nameLength)], as: UTF8.self)
            cursor += 46 + nameLength + extraLength + commentLength
            if name.hasSuffix("/") { continue }   // a folder
            guard method == 0 else { throw Failure.compressed(name) }
            guard !name.hasPrefix("/"), !name.split(separator: "/").contains("..") else { throw Failure.unsafePath(name) }
            // The data follows the local header (its name and extra lengths can differ from the central ones).
            guard u32(localHeader) == 0x0403_4b50 else { throw Failure.notAPackage }
            let offset = localHeader + 30 + u16(localHeader + 26) + u16(localHeader + 28)
            guard offset + size <= bytes.count else { throw Failure.notAPackage }
            result.append(Entry(path: name, offset: offset, size: size))
        }
        // Archive order is the local header order.
        return result.sorted { $0.offset < $1.offset }
    }

    /// The package with every entry dated 2026-01-01 00:00, in place (alignment untouched), so a
    /// package built twice from the same files has the same bytes (D146). Unchanged if it isn't a zip.
    public static func withFixedDates(_ data: Data) -> Data {
        var bytes = [UInt8](data)
        func u16(_ i: Int) -> Int { i + 1 < bytes.count ? Int(bytes[i]) | Int(bytes[i + 1]) << 8 : 0 }
        func u32(_ i: Int) -> Int { i + 3 < bytes.count ? u16(i) | u16(i + 2) << 16 : 0 }
        let date = (2026 - 1980) << 9 | 1 << 5 | 1   // DOS date; the time is 0
        func stamp(_ at: Int) {
            guard at + 3 < bytes.count else { return }
            bytes[at] = 0; bytes[at + 1] = 0
            bytes[at + 2] = UInt8(date & 0xFF); bytes[at + 3] = UInt8(date >> 8)
        }
        var eocd = -1
        var i = bytes.count - 22
        while i >= max(0, bytes.count - 22 - 65_535) {
            if u32(i) == 0x0605_4b50 { eocd = i; break }
            i -= 1
        }
        guard eocd >= 0 else { return data }
        var cursor = u32(eocd + 16)
        for _ in 0..<u16(eocd + 10) {
            guard u32(cursor) == 0x0201_4b50 else { return data }
            stamp(cursor + 12)
            let local = u32(cursor + 42)
            if u32(local) == 0x0403_4b50 { stamp(local + 10) }
            cursor += 46 + u16(cursor + 28) + u16(cursor + 30) + u16(cursor + 32)
        }
        return Data(bytes)
    }

    /// A package of these files: the root layer first, every entry stored and 64-byte aligned, dated as `withFixedDates` does
    /// (D154), so the same files always make the same bytes.
    public static func make(root: (path: String, data: Data), files: [(path: String, data: Data)]) -> Data {
        var out = Data()
        var directory = Data()
        func le16(_ v: Int) -> [UInt8] { [UInt8(v & 0xFF), UInt8(v >> 8 & 0xFF)] }
        func le32(_ v: Int) -> [UInt8] { le16(v & 0xFFFF) + le16(v >> 16 & 0xFFFF) }
        let date = (2026 - 1980) << 9 | 1 << 5 | 1
        let all = [root] + files
        for file in all {
            let name = Array(file.path.utf8)
            let crc = crc32(file.data)
            // The data must start on a multiple of 64: padding goes in the local header's extra field, which needs a
            // 4-byte header of its own (so never 1–3 bytes of it).
            var padding = (64 - (out.count + 30 + name.count) % 64) % 64
            if padding > 0, padding < 4 { padding += 64 }
            let shared = le16(20) + le16(0x0800) + le16(0) + le16(0) + le16(date) + le32(crc) + le32(file.data.count) + le32(file.data.count) + le16(name.count)
            let at = out.count
            out.append(contentsOf: [0x50, 0x4B, 0x03, 0x04] + shared + le16(padding) + name)
            if padding > 0 { out.append(contentsOf: [0xFF, 0xFF] + le16(padding - 4) + [UInt8](repeating: 0, count: padding - 4)) }
            out.append(file.data)
            directory.append(contentsOf: [0x50, 0x4B, 0x01, 0x02] + le16(20) + shared + le16(0) + le16(0) + le16(0) + le16(0) + le32(0) + le32(at) + name)
        }
        let start = out.count
        out.append(directory)
        out.append(contentsOf: [0x50, 0x4B, 0x05, 0x06] + le16(0) + le16(0) + le16(all.count) + le16(all.count) + le32(directory.count) + le32(start) + le16(0))
        return out
    }

    private static let crcTable: [UInt32] = (0..<256).map { i in
        (0..<8).reduce(UInt32(i)) { c, _ in c & 1 == 1 ? 0xEDB8_8320 ^ (c >> 1) : c >> 1 }
    }

    private static func crc32(_ data: Data) -> Int {
        var crc: UInt32 = 0xFFFF_FFFF
        for byte in data { crc = crcTable[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8) }
        return Int(crc ^ 0xFFFF_FFFF)
    }

    /// Writes every file of the package into `folder`. Returns the root layer's path inside it.
    @discardableResult
    public static func unpack(_ data: Data, to folder: URL) throws -> String {
        let list = try entries(data)
        guard let root = list.first(where: { ["usda", "usdc", "usd"].contains(($0.path as NSString).pathExtension.lowercased()) })
        else { throw Failure.notAPackage }
        let fm = FileManager.default
        for entry in list {
            let url = folder.appendingPathComponent(entry.path)
            try fm.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try data.subdata(in: entry.offset..<(entry.offset + entry.size)).write(to: url, options: .atomic)
        }
        return root.path
    }
}
