/// Cooking a model (D154, spec campaigns §6.5). A source layer becomes a package here. Cooked, that package's parts are kept
/// as files: the layer stays at its path, with `<name>.cooked/` beside it for its textures, and a device puts them
/// back together with no USD. This file and `USDZArchive` stand alone: `Scripts/gen-model-cook.sh` joins them with the
/// `model-cook` tool into one source file for the content repository's Action.
public enum ModelCook {
    /// A cooked folder holds this file (so one with no textures is still there) and the package's textures.
    static let marker = "cooked.txt"
    /// Bumped when cooking changes for the same source: a release cooks everything again.
    public static let version = "1"

    /// The folder beside a layer holding the rest of its package.
    public static func cookedFolder(of layer: URL) -> URL {
        layer.deletingPathExtension().appendingPathExtension("cooked")
    }

    public static func isCooked(_ layer: URL) -> Bool {
        FileManager.default.fileExists(atPath: cookedFolder(of: layer).appendingPathComponent(marker).path)
    }

    /// Cooks `source`, writing `layer` and `folder` (a cooked folder, whatever it's called while it's made).
    public static func cook(_ source: URL, layer: URL, folder: URL) throws {
        let data = try package(source)
        let entries = try USDZArchive.entries(data)
        guard let root = entries.first else { throw Failure.notPackaged }
        let fm = FileManager.default
        try fm.createDirectory(at: layer.deletingLastPathComponent(), withIntermediateDirectories: true)
        try fm.createDirectory(at: folder, withIntermediateDirectories: true)
        try data.subdata(in: root.offset..<(root.offset + root.size)).write(to: layer, options: .atomic)
        try Data("\(version)\n".utf8).write(to: folder.appendingPathComponent(marker), options: .atomic)
        for entry in entries.dropFirst() {
            let file = folder.appendingPathComponent(entry.path)
            try fm.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
            try data.subdata(in: entry.offset..<(entry.offset + entry.size)).write(to: file, options: .atomic)
        }
    }

    /// A cooked layer and its folder, put together as a package. The same parts always make the same bytes.
    public static func assemble(_ layer: URL) throws -> Data {
        let folder = cookedFolder(of: layer).standardizedFileURL
        let fm = FileManager.default
        var parts: [(path: String, data: Data)] = []
        if let walker = fm.enumerator(at: folder, includingPropertiesForKeys: [.isRegularFileKey]) {
            for case let file as URL in walker {
                guard try file.resourceValues(forKeys: [.isRegularFileKey]).isRegularFile == true else { continue }
                let path = String(file.standardizedFileURL.path.dropFirst(folder.path.count + 1))
                if path != marker, !file.lastPathComponent.hasPrefix(".") { parts.append((path, try Data(contentsOf: file))) }
            }
        }
        return USDZArchive.make(root: (rootName, try Data(contentsOf: layer)),
                                files: parts.sorted { $0.path < $1.path })
    }

    /// The layer's name inside a package.
    static let rootName = "model.usdc"

    public enum Failure: Error, CustomStringConvertible {
        case unavailable
        case noDefaultPrim
        case notPackaged

        public var description: String {
            switch self {
            case .unavailable: "USD files can't be packaged on this device."
            case .noDefaultPrim: "The model has no default prim to place."
            case .notPackaged: "The package couldn't be written."
            }
        }
    }

    /// Builds the package: a layer that turns the source to Y-up metres and references it,
    /// flattened; every material no mesh binds removed; each remaining texture beside the
    /// layer; packaged with fixed dates, so the same source always makes the same bytes.
    public static func package(_ source: URL) throws -> Data {
        #if canImport(USDKit)
        let fm = FileManager.default
        let work = fm.temporaryDirectory.appendingPathComponent("ModelPackage-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: work.appendingPathComponent("textures"), withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: work) }   // try?: a temporary folder; the system clears it anyway

        // Open through the layer: `USDStage.open(URL)` crashed in a command-line probe (2026-10-29).
        let sourceStage = try USDStage.open(rootLayer: try USDLayer.open(source.path))
        // A Gaussian splat is already a complete capture (D152): flattening it would drop the
        // primitive, and it needs no Y-up conversion of its own. Package it as it stands.
        if sourceStage.descendants.contains(where: { $0.isSchema("ParticleField3DGaussianSplat") }) {
            let data = try sourceStage.exportPackage(options: [.preferSmallTextureFiles(quality: .standard)])
            guard !data.isEmpty else { throw Failure.notPackaged }
            return USDZArchive.withFixedDates(data)
        }
        guard let rootName = sourceStage.rootLayer.defaultPrim.map({ "\($0)" }), !rootName.isEmpty else { throw Failure.noDefaultPrim }
        let zUp = "\(sourceStage.upAxis)".uppercased() == "Z"
        let metres = sourceStage.metersPerUnit > 0 ? sourceStage.metersPerUnit : 1

        // 1. Y-up, metres: Z-up turns -90° about X (its back edge, +Y, then faces -Z). The root
        // has no type of its own, so the source's comes through (a model may be a single Mesh).
        let wrapper = work.appendingPathComponent("wrapper.usda")
        try """
        #usda 1.0
        (
            defaultPrim = "\(rootName)"
            metersPerUnit = 1
            upAxis = "Y"
        )

        def "\(rootName)" (
            kind = "component"
            prepend references = @\(source.standardizedFileURL.path)@
        )
        {
            float xformOp:rotateX = \(zUp ? -90 : 0)
            double3 xformOp:scale = (\(metres), \(metres), \(metres))
            uniform token[] xformOpOrder = ["xformOp:rotateX", "xformOp:scale"]
        }

        """.write(to: wrapper, atomically: true, encoding: .utf8)

        // 2. Flattened, 3. without the materials nothing binds (a shared library holds every look).
        let flat = work.appendingPathComponent("flat.usda")
        try USDStage.open(rootLayer: try USDLayer.open(wrapper.path)).exportFlattened(to: flat)
        let flatStage = try USDStage.open(rootLayer: try USDLayer.open(flat.path))
        var bound = Set<String>()
        let bindings = ["material:binding", "material:binding:preview", "material:binding:full"]
        for prim in flatStage.allDescendants {
            for name in bindings where prim.hasProperty(named: USDToken(stringLiteral: name)) {
                for target in prim.relationship(named: USDToken(stringLiteral: name)).targets { bound.insert(target.description) }
            }
        }
        let materials = flatStage.allDescendants.map(\.path).filter { path in
            flatStage.rootLayer.prim(at: path).map { "\($0.typeName)" == "Material" } ?? false
        }
        for path in materials where !bound.contains(path.description) { _ = flatStage.removePrim(at: path) }
        let pruned = work.appendingPathComponent("model.usda")
        try flatStage.rootLayer.export(to: pruned)

        // 4. Textures beside the layer (flattening made their paths absolute).
        var text = try String(contentsOf: pruned, encoding: .utf8)
        var copied: [String: String] = [:]
        let assetPaths = Set(text.matches(of: /@([^@\n]+)@/).map { String($0.output.1) })
        for path in assetPaths.sorted() where path.hasPrefix("/") {
            let file = URL(fileURLWithPath: path)
            guard fm.fileExists(atPath: file.path) else { continue }
            var name = file.lastPathComponent
            var n = 2
            while copied.values.contains("textures/\(name)") { name = "\(n)-\(file.lastPathComponent)"; n += 1 }
            try fm.copyItem(at: file, to: work.appendingPathComponent("textures/\(name)"))
            copied[path] = "textures/\(name)"
        }
        for (path, local) in copied { text = text.replacingOccurrences(of: "@\(path)@", with: "@\(local)@") }
        // No local paths in what leaves this device (flattening records the layers it read).
        text = text.replacingOccurrences(of: work.path, with: ".").replacingOccurrences(of: source.deletingLastPathComponent().path, with: ".")
        try text.write(to: pruned, atomically: true, encoding: .utf8)

        // 5. One binary layer (text is about half as big again), one package with its textures
        // compressed (AVIF at standard quality: about a quarter of the PNGs, 45–55 dB PSNR on the
        // 3DAssets textures, 2026-10-29), the same bytes every time.
        let binary = work.appendingPathComponent("model.usdc")
        try USDLayer.open(pruned.path).export(to: binary)
        let data = try USDStage.open(rootLayer: try USDLayer.open(binary.path)).exportPackage(options: [.preferSmallTextureFiles(quality: .standard)])
        guard !data.isEmpty else { throw Failure.notPackaged }
        return USDZArchive.withFixedDates(data)
        #else
        throw Failure.unavailable
        #endif
    }
}
