// model-cook  (one job per line on standard input: <source layer> TAB <layer to write> TAB <cooked folder to write>)
//
// Cooks models (D154, spec campaigns §6.5). A line that fails is reported and the rest carry on; the exit code is 1
// if any did.

var failures = 0
var cooked = 0
while let line = readLine() {
    let fields = line.components(separatedBy: "\t")
    guard fields.count == 3 else {
        FileHandle.standardError.write(Data("model-cook: not a job: \(line)\n".utf8))
        failures += 1
        continue
    }
    let (source, layer, folder) = (URL(fileURLWithPath: fields[0]), URL(fileURLWithPath: fields[1]), URL(fileURLWithPath: fields[2]))
    do {
        try autoreleasepool { try ModelCook.cook(source, layer: layer, folder: folder) }
        cooked += 1
    } catch {
        FileHandle.standardError.write(Data("model-cook: \(source.lastPathComponent): \(error)\n".utf8))
        failures += 1
    }
}
print("cooked \(cooked), failed \(failures)")   // print: the tool's summary
exit(failures == 0 ? 0 : 1)
